func lengthOfLongestSubstring(s string) int {
	last := map[byte]int{}
	left, best := 0, 0
	for right := 0; right < len(s); right++ {
		ch := s[right]
		if p, ok := last[ch]; ok && p >= left {
			left = p + 1
		}
		last[ch] = right
		if right-left+1 > best {
			best = right - left + 1
		}
	}
	return best
}

