func maxSlidingWindow(nums []int, k int) []int {
	q := []int{}
	head := 0
	res := []int{}
	for i, x := range nums {
		for len(q) > head && nums[q[len(q)-1]] <= x {
			q = q[:len(q)-1]
		}
		q = append(q, i)
		if q[head] <= i-k {
			head++
		}
		if i >= k-1 {
			res = append(res, nums[q[head]])
		}
	}
	return res
}

