func minWindow(s string, t string) string {
	need := map[byte]int{}
	for i := 0; i < len(t); i++ {
		need[t[i]]++
	}
	win := map[byte]int{}
	have, want := 0, len(need)
	left := 0
	bl, br := 0, -1
	best := len(s) + 1
	for right := 0; right < len(s); right++ {
		ch := s[right]
		if _, ok := need[ch]; ok {
			win[ch]++
			if win[ch] == need[ch] {
				have++
			}
		}
		for have == want {
			if right-left+1 < best {
				best = right - left + 1
				bl, br = left, right
			}
			c := s[left]
			if _, ok := need[c]; ok {
				win[c]--
				if win[c] < need[c] {
					have--
				}
			}
			left++
		}
	}
	if best <= len(s) {
		return s[bl : br+1]
	}
	return ""
}

