func rotate(nums []int, k int) {
	n := len(nums)
	k %= n
	rev := func(i, j int) {
		for i < j {
			nums[i], nums[j] = nums[j], nums[i]
			i++
			j--
		}
	}
	rev(0, n-1)
	rev(0, k-1)
	rev(k, n-1)
}

